(()=>{'use strict';const copy=document.querySelector('#copy-discord');if(copy)copy.onclick=async()=>{const text=document.querySelector('#discord-handle').textContent;try{await navigator.clipboard.writeText(text);document.querySelector('#copy-status').textContent='Discord username copied.';}catch{document.querySelector('#copy-status').textContent='Copy this username: '+text;}};const search=document.querySelector('#video-search'),source=document.querySelector('#video-source');if(search){function filter(){let count=0;const q=search.value.toLowerCase().trim();document.querySelectorAll('.video-card').forEach(c=>{c.hidden=!(c.dataset.search.includes(q)&&(source.value==='all'||c.dataset.source===source.value));if(!c.hidden)count++;else if(c.querySelector('iframe')){c.querySelector('iframe').remove();c.querySelector('.play-video').hidden=false;}});document.querySelector('#video-count').textContent=count+' matching videos';document.querySelector('#video-empty').hidden=count>0;}search.addEventListener('input',filter);source.addEventListener('change',filter);}document.querySelectorAll('.play-video').forEach(button=>button.onclick=()=>{const id=button.dataset.video;if(!/^[A-Za-z0-9_-]{11}$/.test(id))return;document.querySelectorAll('.video-frame iframe').forEach(f=>{f.parentNode.querySelector('button').hidden=false;f.remove();});const frame=document.createElement('iframe');frame.src='https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1';frame.title=button.getAttribute('aria-label');frame.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';button.hidden=true;button.parentNode.append(frame);});})();